/**
 * =============================================================
 *  Core JS — intensification-independent (dipakai semua proyek)
 * =============================================================
 *  Berisi:
 *   1. window.Lokasi  : pembentuk URL endpoint untuk halaman
 *   2. window.Beranda : preloader + refresh token CSRF
 *   3. Sidebar       : buka submenu yang sedang aktif
 *
 *  URL dropdown diberikan oleh layout (bernilai PHP):
 *      const urlDropdown = '<?= site_url('dropdown') ?>';
 *      const urlVendor   = '<?= site_url('vendor') ?>/';
 * =============================================================
 */

window.Lokasi = {
    /**
     * Basis URL untuk seluruh endpoint core (prefix /vendor).
     * Disuntik oleh layout lewat `const urlVendor = '.../vendor/';`.
     *
     * @returns {string} URL dasar yang selalu berakhiran garis miring
     */
    vendor: function () {
        return typeof urlVendor === 'string' ? urlVendor : '/vendor/';
    },
    /**
     * @param {string} basis  URL dasar, default URL halaman saat ini
     * @param {Object} endpoint Kumpulan endpoint relatif, mis. {simpan:'simpan', hapus:'hapus'}
     * @returns {Object} Objek yang sama, siap dipakai
     */
    endpoint: function (endpoint, basis) {
        const base = basis || window.location.href.replace(/[^/]*$/, '');
        Object.keys(endpoint || {}).forEach(function (key) {
            endpoint[key] = `${base}${endpoint[key]}`;
        });
        return endpoint;
    }
};

window.Beranda = {
    /**
     * Siapkan header X-CSRF-TOKEN untuk seluruh request $.ajax.
     * Aman dipanggil walau meta csrf-token tidak ada (mis. CSRF dimatikan).
     */
    refreshCsrf: function () {
        const meta = document.querySelector('meta[name="csrf-token"]');

        if (!meta) {
            return false;
        }

        $.ajaxSetup({ headers: { 'X-CSRF-TOKEN': meta.getAttribute('content') } });

        return true;
    },

    showPreloader: function () {
        const $pre = $('.preloader');

        $pre.addClass('no-transition');
        $pre.css({ height: '100%', display: 'flex' });
        $pre.children().show();
    },

    hidePreloader: function () {
        const $pre = $('.preloader');

        $pre.css('height', 0);

        setTimeout(function () {
            $pre.children().hide();
        }, 500);
    }
};

document.addEventListener('DOMContentLoaded', function () {
    Beranda.refreshCsrf();

    const activeSubmenus = document.querySelectorAll('.nav-sidebar .nav-treeview .nav-link.active');

    activeSubmenus.forEach(function (link) {
        const parentNavItems = link.closest('.nav-treeview')?.parentElement.closest('.nav-item');

        if (parentNavItems) {
            parentNavItems.classList.add('menu-is-opening', 'menu-open');

            const parentNavLink = parentNavItems.querySelector(':scope > .nav-link');

            if (parentNavLink) {
                parentNavLink.classList.add('active');
            }
        }
    });
});